# Inglenook for hexyl: Inglenook Night.
# Source this from your profile. Needs hexyl 0.17 or newer.

# The offset column on the left.
$env:HEXYL_COLOR_OFFSET = '#8f887f'
# The null byte.
$env:HEXYL_COLOR_NULL = '#8f887f'
# Printable ASCII characters.
$env:HEXYL_COLOR_ASCII_PRINTABLE = '#91bc88'
# Spaces, tabs and line breaks.
$env:HEXYL_COLOR_ASCII_WHITESPACE = '#b1aa9e'
# Other ASCII bytes, such as control characters.
$env:HEXYL_COLOR_ASCII_OTHER = '#da9f7c'
# Bytes above 0x7F.
$env:HEXYL_COLOR_NONASCII = '#cb9cc6'
